#include <zephyr/drivers/retained_mem.h>
#include <zephyr/device.h>
#include <zephyr/kernel.h>
#include <zephyr/init.h>
#include <string.h>
#include <errno.h>
#include <zephyr/devicetree.h>

struct retained_mem_sram_config {
    uintptr_t base_address;
    size_t size;
};

static int retained_mem_sram_read(const struct device *dev, size_t offset, void *data, size_t len)
{
    const struct retained_mem_sram_config *config = dev->config;
    uint8_t *base_addr = (uint8_t *)config->base_address;

    if ((offset + len) > config->size) {
        return -EINVAL;
    }

    memcpy(data, base_addr + offset, len);
    return 0;
}

static int retained_mem_sram_write(const struct device *dev, size_t offset, const void *data, size_t len)
{
    const struct retained_mem_sram_config *config = dev->config;
    uint8_t *base_addr = (uint8_t *)config->base_address;

    if ((offset + len) > config->size) {
        return -EINVAL;
    }

    memcpy(base_addr + offset, data, len);
    return 0;
}

static int retained_mem_sram_clear(const struct device *dev, size_t offset, size_t len)
{
    const struct retained_mem_sram_config *config = dev->config;
    uint8_t *base_addr = (uint8_t *)config->base_address;

    if ((offset + len) > config->size) {
        return -EINVAL;
    }

    memset(base_addr + offset, 0, len);
    return 0;
}

static int retained_mem_sram_init(const struct device *dev)
{
    ARG_UNUSED(dev);
    return 0;
}

static const struct retained_mem_driver_api retained_mem_sram_api = {
    .read = retained_mem_sram_read,
    .write = retained_mem_sram_write,
    .clear = retained_mem_sram_clear,
};

#define RETAINED_MEM_NODE DT_CHOSEN(zephyr_retained_mem)

#if DT_NODE_HAS_STATUS(RETAINED_MEM_NODE, okay)

static const struct retained_mem_sram_config retained_mem_sram_cfg = {
    .base_address = DT_REG_ADDR(RETAINED_MEM_NODE),
    .size = DT_REG_SIZE(RETAINED_MEM_NODE),
};

DEVICE_DT_DEFINE(RETAINED_MEM_NODE, retained_mem_sram_init, NULL,
                 NULL, &retained_mem_sram_cfg,
                 POST_KERNEL, CONFIG_RETAINED_MEM_INIT_PRIORITY,
                 &retained_mem_sram_api);

#endif /* DT_NODE_HAS_STATUS(RETAINED_MEM_NODE, okay) */
